29	    @Test public void hasAssociatedControls() {
30	        //"button", "fieldset", "input", "keygen", "object", "output", "select", "textarea"
31	        String html = "<form id=1><button id=1><fieldset id=2 /><input id=3><keygen id=4><object id=5><output id=6>" +
32	                "<select id=7><option></select><textarea id=8><p id=9>";
