39	    @Test public void createsFormData() {
40	        String html = "<form><input name='one' value='two'><select name='three'><option value='not'>" +
41	                "<option value='four' selected><option value='five' selected><textarea name=six>seven</textarea>" +
42	                "<input name='seven' type='radio' value='on' checked><input name='seven' type='radio' value='off'>" +
43	                "<input name='eight' type='checkbox' checked><input name='nine' type='checkbox' value='unset'>" +
44	                "<input name='ten' value='text' disabled>" +
45	                "<input name='eleven' value='text' type='button'>" +
46	                "<input name='twelve' value='text' type='image'>" +
47	                "<button name='thirteen' value='go'>go</button>" +
48	                "</form>";
49	        Document doc = Jsoup.parse(html);
50	        FormElement form = (FormElement) doc.select("form").first();
51	        List<Connection.KeyVal> data = form.formData();
52	
53	        assertEquals(5, data.size());
54	        assertEquals("one=two", data.get(0).toString());
55	        assertEquals("three=four", data.get(1).toString()); // single select: first enabled selected only
56	        assertEquals("six=seven", data.get(2).toString());
57	        assertEquals("seven=on", data.get(3).toString()); // set
58	        assertEquals("eight=on", data.get(4).toString()); // default
59	        // nine should not appear, not checked checkbox
60	        // ten should not appear, disabled
61	        // eleven should not appear, button
62	        // twelve should not appear, image
63	        // thirteen should not appear, <button> element
64	    }
