66	    @Test public void formDataUsesFirstAttribute() {
67	        String html = "<form><input name=test value=foo name=test2 value=bar>";
68	        Document doc = Jsoup.parse(html);
69	        FormElement form = (FormElement) doc.selectFirst("form");
70	        assertEquals("test=foo", form.formData().get(0).toString());
