73	    @Test public void createsSubmitableConnection() {
74	        String html = "<form action='/search'><input name='q'></form>";
75	        Document doc = Jsoup.parse(html, "http://example.com/");
76	        doc.select("[name=q]").attr("value", "jsoup");
