import org.jsoup.Jsoup;
import org.jsoup.nodes.*;

public class Probe {
    static void indent(Element e, int d) {
        StringBuilder sb = new StringBuilder();
        for (int i=0;i<d;i++) sb.append("  ");
        System.out.println(sb + "<" + e.tagName() + (e.id().isEmpty()?"":("#"+e.id())) + ">");
        for (Element c : e.children()) indent(c, d+1);
    }
    public static void main(String[] a) {
        String html = "<html><body><table>" +
            "<form action=\"/hello.php\" method=\"post\">" +
            "<tr><td>User:<input type=\"text\" name=\"user\" /></td></tr>" +
            "<tr><td><input type=\"submit\" name=\"login\" /></td></tr>" +
            "</form></table></body></html>";
        Document doc = Jsoup.parse(html);
        indent(doc, 0);
        Element user = doc.selectFirst("input[name=user]");
        Element form = doc.selectFirst("form");
        System.out.println("user.parent chain contains form? " + user.parents().contains(form));
        System.out.println("form == nearest ancestor form? walking:");
        for (Element p = user.parent(); p != null; p = p.parent())
            System.out.println("   parent: " + p.tagName());
    }
}
