package org.jsoup.nodes;

import org.jsoup.Connection;
import org.jsoup.Jsoup;
import org.jsoup.helper.HttpConnection;
import org.jsoup.helper.Validate;
import org.jsoup.internal.SharedConstants;
import org.jsoup.internal.StringUtil;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Elements;
import org.jsoup.select.Evaluator;
import org.jsoup.select.Selector;
import org.jspecify.annotations.Nullable;

import java.util.ArrayList;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Set;

/**
 * An HTML Form Element provides ready access to the form fields/controls that are associated with it. It also allows a
 * form to easily be submitted.
 */
public class FormElement extends Element {
    // Form-associated elements that may carry a form= ownership attribute, per the HTML spec
    private static final String[] FormOwnerTags =
        {"input", "keygen", "object", "select", "textarea"};
    private static final Evaluator formOwner =
        Selector.evaluatorOf(StringUtil.join(FormOwnerTags, ", "));
    // contains form submittable elements that were linked during the parse (and due to parse rules, may no longer be a child of this form)
    private static final Evaluator submittable = Selector.evaluatorOf(StringUtil.join(SharedConstants.FormSubmitTags, ", "));

    private final Elements linkedEls = new Elements();

    /**
     * Create a new, standalone form element.
     *
     * @param tag        tag of this element
     * @param baseUri    the base URI
     * @param attributes initial attributes
     */
    public FormElement(Tag tag, @Nullable String baseUri, @Nullable Attributes attributes) {
        super(tag, baseUri, attributes);
    }

    /**
     * Get the list of form control elements associated with this form.
     * <p>Association follows the HTML form ownership rules and is recomputed on every call, so moving nodes or changing
     * a control's {@code form} attribute or a form's {@code id} is picked up immediately:</p>
     * <ul>
     * <li>a listed control ({@code input}, {@code keygen}, {@code object}, {@code select}, {@code textarea}) that has a
     * {@code form} attribute belongs to the element in the same document whose {@code id} matches it, but only when that
     * element is itself a {@code FormElement}; this lets a control sit outside the form, or even inside another form —
     * the explicit owner takes precedence over an ancestor form;</li>
     * <li>a control without a {@code form} attribute belongs to its nearest ancestor {@code FormElement};</li>
     * <li>if there is no ancestor form, a control linked to this form by the parser (for example, inputs hoisted out of
     * a form during table recovery) remains associated with it;</li>
     * <li>a {@code form} attribute that names a missing element, or an element that is not a form, leaves the control
     * unassociated (it does not fall back to an ancestor).</li>
     * </ul>
     * The returned controls are in document order and de-duplicated.
     * @return form controls associated with this element
     */
    public Elements elements() {
        Elements associated = new Elements();
        Set<Element> seen = Collections_newIdentitySet();

        Document owner = ownerDocument();
        if (owner != null) {
            // form-attribute owners are resolved document-wide and take precedence over ancestry
            for (Element el : owner.select(formOwner)) {
                if (!el.hasAttr("form")) continue;
                String formId = el.attr("form");
                if (formId.isEmpty()) continue;
                Element target = owner.getElementById(formId);
                if (target == this && !seen.contains(el)) {
                    seen.add(el);
                    associated.add(el);
                }
            }
        }

        // current descendant controls (tree order), associated by ancestry
        for (Element el : select(submittable)) {
            if (ownedByAncestor(el) && seen.add(el))
                associated.add(el);
        }

        // parse-linked controls: kept only when they have no other owner, and never when a form= attr overrides us
        for (Element linkedEl : linkedEls) {
            if (linkedEl.ownerDocument() == null || seen.contains(linkedEl)) continue;
            if (hasExplicitFormOwner(linkedEl)) continue;
            if (nearestAncestorForm(linkedEl) != null) continue;
            seen.add(linkedEl);
            associated.add(linkedEl);
        }

        return associated;
    }

    /**
     * A descendant control is owned by this form unless it carries a {@code form} attribute (which always overrides
     * ancestry), or a nearer ancestor form intervenes.
     */
    private boolean ownedByAncestor(Element el) {
        if (hasExplicitFormOwner(el)) return false;
        return nearestAncestorForm(el) == this;
    }

    /**
     * Find the nearest {@code FormElement} ancestor of {@code el}, if any.
     */
    private static @Nullable FormElement nearestAncestorForm(Element el) {
        for (Element parent = el.parent(); parent != null && !parent.nameIs("#root"); parent = parent.parent()) {
            if (parent instanceof FormElement) return (FormElement) parent;
        }
        return null;
    }

    /**
     * A control has an explicit owner when it carries a non-empty {@code form} attribute naming a form in its document.
     * When set, the attribute wins outright: a dangling or non-form target means the control has no owner at all.
     */
    private static boolean hasExplicitFormOwner(Element el) {
        if (!el.hasAttr("form") || el.attr("form").isEmpty()) return false;
        Document owner = el.ownerDocument();
        if (owner == null) return true; // attribute present but no document to resolve it: overrides ancestry
        Element target = owner.getElementById(el.attr("form"));
        return target instanceof FormElement;
    }

    private static Set<Element> Collections_newIdentitySet() {
        return java.util.Collections.newSetFromMap(new IdentityHashMap<Element, Boolean>());
    }

    /**
     * Add a form control element to this form.
     * @param element form control to add
     * @return this form element, for chaining
     */
    public FormElement addElement(Element element) {
        linkedEls.add(element);
        return this;
    }

    @Override
    protected void removeChild(Node out) {
        super.removeChild(out);
        linkedEls.remove(out);
    }

    /**
     Prepare to submit this form. A Connection object is created with the request set up from the form values. This
     Connection will inherit the settings and the cookies (etc) of the connection/session used to request this Document
     (if any), as available in {@link Document#connection()}
     <p>You can then set up other options (like user-agent, timeout, cookies), then execute it.</p>

     @return a connection prepared from the values of this form, in the same session as the one used to request it
     @throws IllegalArgumentException if the form's action URL is missing its base URI, or the form's absolute action
     URL cannot otherwise be determined. Make sure you pass the document's base URI when parsing.
     */
    public Connection submit() {
        String action = hasAttr("action") ? requireAbsUrl("action") : requireBaseUri();
        Connection.Method method = attr("method").equalsIgnoreCase("POST") ?
            Connection.Method.POST : Connection.Method.GET;

        Document owner = ownerDocument();
        Connection connection = owner != null? owner.connection().newRequest() : Jsoup.newSession();
        return connection.url(action)
            .data(formData())
            .method(method);
    }

    private String requireBaseUri() {
        String baseUri = baseUri();
        Validate.notEmpty(baseUri, "Could not determine a form action URL for submit. Ensure you set a base URI when parsing.");
        return baseUri;
    }

    private String requireAbsUrl(String attrKey) {
        String action = absUrl(attrKey);
        Validate.notEmpty(action, String.format("Could not resolve the form's absolute %s URL for submit. Ensure you set a base URI when parsing.", attrKey));
        return action;
    }

    /**
     Get the data that this form submits. The returned list is computed fresh from the form's associated controls in
     document order, on every call, and is independent of the DOM: modifying the list does not change the document, and
     controls sharing a name each contribute their own entry.
     <p>The controls are filtered following the HTML form submission rules:</p>
     <ul>
     <li>controls that are themselves {@code disabled}, or that are inside a {@code disabled} {@code <fieldset>}, are
     skipped — except for controls inside that fieldset's first {@code <legend>}; a nested disabled fieldset is not
     re-enabled by an outer fieldset's legend;</li>
