import org.jsoup.Jsoup;
import org.jsoup.nodes.*;
import org.jsoup.select.Elements;
import java.util.List;

public class Ownership {
    static int pass=0, fail=0;
    static void check(String name, boolean ok) {
        System.out.println((ok?"PASS ":"FAIL ")+name);
        if(ok)pass++;else fail++;
    }
    static String names(Elements es){ StringBuilder b=new StringBuilder(); for(Element e:es){if(b.length()>0)b.append(",");b.append(e.attr("name").isEmpty()?e.tagName():e.attr("name"));} return b.toString();}

    public static void main(String[] x) {
        // 1. external control via form= attribute
        Document d = Jsoup.parse("<body><form id=f1><input name=a></form><input name=b form=f1></body>");
        FormElement f1 = (FormElement) d.getElementById("f1");
        check("external form= owned", f1.elements().size()==2 && names(f1.elements()).equals("a,b"));

        // 2. control inside another form, form= wins over ancestor
        d = Jsoup.parse("<form id=f1><input name=outer></form><form id=f2><input name=inner form=f1></form>");
        f1 = (FormElement) d.getElementById("f1");
        FormElement f2 = (FormElement) d.getElementById("f2");
        check("form= overrides ancestor (f1)", names(f1.elements()).equals("outer,inner"));
        check("form= overrides ancestor (f2)", names(f2.elements()).equals(""));

        // 3. missing target -> unowned
        d = Jsoup.parse("<form id=f1><input name=a></form><input name=b form=nope>");
        f1 = (FormElement) d.getElementById("f1");
        check("missing target unowned", names(f1.elements()).equals("a"));

        // 4. target not a form -> unowned
        d = Jsoup.parse("<form id=f1><input name=a></form><div id=d1></div><input name=b form=d1><input name=c>");
        f1 = (FormElement) d.getElementById("f1");
        // c is outside form, no attr, no parser link -> unowned
        check("non-form target unowned", names(f1.elements()).equals("a"));

        // 5. form= empty -> falls back to ancestor (nearest)
        d = Jsoup.parse("<form id=f1><input name=a form=''></form>");
        f1 = (FormElement) d.getElementById("f1");
        check("empty form= uses ancestor", names(f1.elements()).equals("a"));

        // 6. recompute after moving node
        d = Jsoup.parse("<form id=f1><input name=a></form><form id=f2></form>");
        f1 = (FormElement) d.getElementById("f1"); f2 = (FormElement) d.getElementById("f2");
        Element a = d.selectFirst("input[name=a]");
        check("before move", names(f1.elements()).equals("a") && f2.elements().isEmpty());
        f2.appendChild(a);
        check("after move to f2", f1.elements().isEmpty() && names(f2.elements()).equals("a"));

        // 7. recompute after changing form attr / form id
        d = Jsoup.parse("<form id=f1></form><input name=b>");
        f1 = (FormElement) d.getElementById("f1");
        Element b = d.selectFirst("input[name=b]");
        check("ext no attr unowned", f1.elements().isEmpty());
        b.attr("form","f1");
        check("set form attr -> owned", names(f1.elements()).equals("b"));
        f1.attr("id","renamed");
        check("rename form id -> lost", f1.elements().isEmpty());
        b.attr("form","renamed");
        check("repoint form attr -> owned", names(f1.elements()).equals("b"));

        // 8. document order with external elements interleaved
        d = Jsoup.parse("<input name=z form=f1><form id=f1><input name=a></form><input name=m form=f1>");
        f1 = (FormElement) d.getElementById("f1");
        check("document order dedup", names(f1.elements()).equals("z,a,m"));

        // 9. duplicate ownership dedup
        d = Jsoup.parse("<form id=f1><input name=a></form>");
        f1 = (FormElement) d.getElementById("f1");
        f1.addElement(d.selectFirst("input[name=a]")); // duplicate link
        check("dedup", f1.elements().size()==1);

        // 10. keygen/object/select/textarea form=
        d = Jsoup.parse("<form id=f1></form><select name=s form=f1><option value=1></select><textarea name=t form=f1>x</textarea>");
        f1 = (FormElement) d.getElementById("f1");
        check("other tags form=", names(f1.elements()).equals("s,t"));

        // 11. disabled filtering still applies to externally owned control
        d = Jsoup.parse("<form id=f1></form><input name=off form=f1 disabled><input name=on form=f1>");
        f1 = (FormElement) d.getElementById("f1");
        List<Connection.KeyVal> fd = f1.formData();
        check("external disabled filtered", fd.size()==1 && fd.get(0).toString().equals("on="));

        // 12. fieldset first-legend exemption for external? fieldset is external wrapper (not inside form)
        d = Jsoup.parse("<form id=f1></form><fieldset disabled form=f1><input name=a form=f1><legend><input name=b form=f1></legend></fieldset>");
        f1 = (FormElement) d.getElementById("f1");
        fd = f1.formData();
        StringBuilder fds=new StringBuilder(); for(Connection.KeyVal k:fd){if(fds.length()>0)fds.append(",");fds.append(k.toString());}
        // fieldset itself not submittable; a disabled by fieldset; b exempt
        check("fieldset legend external", fds.toString().equals("b="));

        // 13. submit absolute action unresolvable -> IAE
        d = Jsoup.parse("<form action='/search'><input name=q></form>"); // no baseUri
        f1 = (FormElement) d.selectFirst("form");
        boolean threw=false; try { f1.submit(); } catch (IllegalArgumentException e){ threw=true; System.out.println("   msg: "+e.getMessage()); }
        check("relative action no base -> IAE", threw);

        // 14. submit no action no base -> IAE (existing)
        d = Jsoup.parse("<form></form>");
        f1 = (FormElement) d.selectFirst("form");
        threw=false; try { f1.submit(); } catch (IllegalArgumentException e){ threw=true; }
        check("no action no base -> IAE", threw);

        // 15. submit with base works, request data == formData
        d = Jsoup.parse("<form action='/search' method=post><input name=q></form>", "http://example.com/");
        f1 = (FormElement) d.selectFirst("form");
        Connection c = f1.submit();
        check("method post", c.request().method()==Connection.Method.POST);
        check("url", c.request().url().toExternalForm().equals("http://example.com/search"));
        @SuppressWarnings("unchecked")
        List<Connection.KeyVal> rd = (List<Connection.KeyVal>) c.request().data();
        check("request data == formData count", rd.size()==f1.formData().size() && rd.get(0).toString().equals("q="));

        // 16. adopted form (parser link, no ancestor, no attr) still retained
        d = Jsoup.parse("<table><form id=f1 action='/x'><tr><td><input name=u></td></tr></form></table>");
        f1 = (FormElement) d.getElementById("f1");
        check("adopted retained", names(f1.elements()).equals("u"));
        // and formData carries it
        check("adopted formData", f1.formData().size()==1 && f1.formData().get(0).key().equals("u"));

        // 17. adopted input given form= to a different form -> moves away
        d = Jsoup.parse("<table><form id=f1 action='/x'><tr><td><input name=u form=f2></td></tr></form></table><form id=f2></form>");
        f1 = (FormElement) d.getElementById("f1"); f2 = (FormElement) d.getElementById("f2");
        check("adopted + form= moves to f2", f1.elements().isEmpty() && names(f2.elements()).equals("u"));

        // 18. external controls included in formData document order along with descendants
        d = Jsoup.parse("<input name=e form=f1 value=E><form id=f1><input name=i value=I></form>");
        f1 = (FormElement) d.getElementById("f1");
        fd = f1.formData();
        fds.setLength(0); for(Connection.KeyVal k:fd){if(fds.length()>0)fds.append(",");fds.append(k.toString());}
        check("formData order ext+desc", fds.toString().equals("e=E,i=I"));

        System.out.println("\nRESULT pass="+pass+" fail="+fail);
        if(fail>0) System.exit(1);
    }
}
